import { FormEngine, type FormEngineConfig } from "@/components/bevelui/form-engine";

const config: FormEngineConfig = {
  mode: "multi-step",
  validation: "per-step",
  steps: [
    {
      id: "account",
      title: "Create your account",
      description: "Your login details.",
      fields: [
        { key: "name", variant: "text", label: "Full name", required: true },
        { key: "email", variant: "email", label: "Email", required: true },
        { key: "password", variant: "password", label: "Password", required: true },
      ],
    },
    {
      id: "plan",
      title: "Choose a plan",
      fields: [
        {
          key: "plan",
          variant: "card-select",
          label: "Plan",
          props: {
            options: [
              { value: "free", label: "Free", description: "$0/mo" },
              { value: "pro", label: "Pro", description: "$12/mo" },
            ],
          },
        },
      ],
    },
  ],
  onSubmit: async (values) => {
    await createAccount(values);
  },
};

export default function OnboardingPage() {
  return <FormEngine config={config} />;
}

import { z } from "zod";
import {
  FormEngine,
  createZodPlugin,
} from "@/components/bevelui/form-engine";

const schemas = {
  0: z.object({
    name: z.string().min(2, "Name must be at least 2 characters"),
    email: z.string().email("Enter a valid email address"),
    password: z.string().min(8, "Password must be at least 8 characters"),
  }),
  1: z.object({
    plan: z.enum(["free", "pro"], { required_error: "Please select a plan" }),
  }),
};

<FormEngine
  config={config}
  plugins={[createZodPlugin(schemas)]}
/>

import {
  createZodPlugin,
  createLogPlugin,
  createAnalyticsPlugin,
} from "@/components/bevelui/form-engine";

<FormEngine
  config={config}
  plugins={[
    createZodPlugin(schemas),
    createLogPlugin(),
    createAnalyticsPlugin((event, data) =>
      mixpanel.track(event, data)
    ),
  ]}
/>

const serverValidationPlugin: FormEnginePlugin = {
  name: "server-validation",
  onValidate: async (step, values) => {
    if (step !== 0) return true;
    // Check username availability on step 0
    const res = await fetch(`/api/check-email?email=${values.email}`);
    const { available } = await res.json();
    return available;
  },
};

